"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[99492],{99492:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-devotion-of-suspect-x.png\\"\\n          title=\\"The Devotion of Suspect X\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Jaein\\"\\n          publishedDate=\\"2017-08-30\\"\\n          isbn=\\"9788990982704\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n\\nThis work shifts from the traditional mystery grammar of ```who is the culprit``` to the questions of <mark>why</mark> (why does he risk everything to protect her?) and <mark>how</mark> (what is the reality of the perfect alibi he designed?).  \\n<br>\\nThe reader does not track the truth with the detective, but experiences the accomplice-like psychology of siding with the protagonist and wishing for his plan to succeed.  \\nBy setting the victim as an atrocious person and depicting the perpetrator as someone to be protected, the author created a device for the reader to feel such emotions.  \\n<br>\\nThe <mark>P≠NP</mark> problem symbolically shows the protagonist\'s criminal philosophy.  \\n```Which is simpler: creating an answer for yourself, or judging if someone else\'s answer is correct?``` This question metaphorically represents the core of this problem.  \\n<br>\\nAs expected, it is the author\'s representative work."}')}}]);